import{c as e,Q as s,j as t,m as n}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Claude Fable 5: Hidden Features Most People Have No Idea About.","description":"","frontmatter":{"url":"https://x.com/kirillk_web3/status/2064670806240535033","title":"Claude Fable 5: Hidden Features Most People Have No Idea About.","author":"kirillk_web3","archived":"2026-07-03T00:00:00.000Z","handle":"@kirillk_web3","published":"2026-06-10T00:00:00.000Z","stats":"420 likes · 55 retweets · 1728 bookmarks · 1311623 views","tags":["fable5","capabilities","vision","memory","data-retention","prompts"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-10-@kirillk_web3-535033.md","filePath":"research/tweets/2026-06-10-@kirillk_web3-535033.md","lastUpdated":1785909234000}'),i={name:"research/tweets/2026-06-10-@kirillk_web3-535033.md"};function l(o,a,p,r,d,c){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="claude-fable-5-hidden-features-most-people-have-no-idea-about-—-kirillk-web3" tabindex="-1">Claude Fable 5: Hidden Features Most People Have No Idea About. — @kirillk_web3 <a class="header-anchor" href="#claude-fable-5-hidden-features-most-people-have-no-idea-about-—-kirillk-web3" aria-label="Permalink to &quot;Claude Fable 5: Hidden Features Most People Have No Idea About. — @kirillk_web3&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/kirillk_web3/status/2064670806240535033" target="_blank" rel="noreferrer">https://x.com/kirillk_web3/status/2064670806240535033</a><strong>作者</strong>：kirillk_web3（@kirillk_web3） <strong>發布日期</strong>：2026-06-10 <strong>收錄日期</strong>：2026-07-03 <strong>類型</strong>：Twitter Article <strong>統計</strong>：420 likes · 55 retweets · 1728 bookmarks · 1311623 views</p><hr><h2 id="全文摘要" tabindex="-1">全文摘要 <a class="header-anchor" href="#全文摘要" aria-label="Permalink to &quot;全文摘要&quot;">​</a></h2><p><strong>定位</strong>：Fable 5 官方文件中的 10 個「隱藏特性」，以能力展示形式呈現，附 10 個測試 prompt。</p><h3 id="_10-個特性-來自官方文件" tabindex="-1">10 個特性（來自官方文件） <a class="header-anchor" href="#_10-個特性-來自官方文件" aria-label="Permalink to &quot;10 個特性（來自官方文件）&quot;">​</a></h3><ol><li><strong>打通寶可夢 FireRed（僅用視覺）</strong>：不靠 helper harness，只用原始遊戲截圖從頭打通；現為 vision tasks SOTA。</li><li><strong>Stripe 50M 行代碼庫遷移（一天）</strong>：Ruby codebase，正常需要整隊兩個月。</li><li><strong>記憶效能是 Opus 4.8 的 3 倍</strong>：Slay the Spire 遊戲測試；持久檔案記憶讓 Fable 5 到達最終章的頻率是 Opus 的 3 倍。</li><li><strong>14 個蛋白質靶點中 9 個出藥物候選</strong>：Mythos 5 在無人輔助下選 binding sites、跑蛋白設計工具、從失敗恢復；速度快 10 倍；一項假設被獨立實驗室論文佐證。</li><li><strong>從物理第一原理模擬太陽系</strong>：自推行星軌道方程式，預測日食；未使用現成庫。</li><li><strong>自主玩 Factorio 建工廠</strong>：長期規劃、資源管理、複雜系統理解。</li><li><strong>建 CAD 編輯器 + 在裡面建 3D 模型</strong>：工具本身和工具輸出都由 Fable 5 在同一 session 完成。</li><li><strong>用 code 作音樂（從未聽過音樂）</strong>：EDM 混音與流體模擬同步，透過 pattern 理解音樂結構。</li><li><strong>基因組研究超越 Science 期刊論文（體積小 100 倍）</strong>：138 個動物物種單細胞數據，訓練自定義 ML 模型，超越 Science 論文，僅需高層人工指導，自主工作超過一週。</li><li><strong>無法被 jailbreak（1000+ 小時測試、零成功）</strong>：內部 bug bounty + 外部紅隊，首個通過此層次安全測試的公開 Mythos-class 模型。</li></ol><h3 id="_10-個測試-prompt-直接可用" tabindex="-1">10 個測試 Prompt（直接可用） <a class="header-anchor" href="#_10-個測試-prompt-直接可用" aria-label="Permalink to &quot;10 個測試 Prompt（直接可用）&quot;">​</a></h3><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Test #1 — Vision</span></span>
<span class="line"><span>Look at this screenshot carefully.</span></span>
<span class="line"><span>List every UI element you can see.</span></span>
<span class="line"><span>Then tell me: if this were a broken product,</span></span>
<span class="line"><span>what are the 3 most likely UX problems based on the layout?</span></span></code></pre></div><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Test #2 — 長自主 coding</span></span>
<span class="line"><span>Read all these files carefully.</span></span>
<span class="line"><span>Identify the single most important refactor</span></span>
<span class="line"><span>that would improve maintainability.</span></span>
<span class="line"><span>Then do it. Show me the before and after.</span></span>
<span class="line"><span>Explain every decision you made.</span></span></code></pre></div><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Test #3 — Memory/notes</span></span>
<span class="line"><span>I&#39;m going to work with you on a complex project today.</span></span>
<span class="line"><span>Create a running notes file as we go.</span></span>
<span class="line"><span>Every time I give you new information, update the notes.</span></span>
<span class="line"><span>At any point I can ask &quot;what do we know so far&quot;</span></span>
<span class="line"><span>and you give me the current state.</span></span></code></pre></div><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Test #7 — Research synthesis</span></span>
<span class="line"><span>Read all of these carefully.</span></span>
<span class="line"><span>Find the one claim that appears in all of them</span></span>
<span class="line"><span>but is slightly different in each.</span></span>
<span class="line"><span>Explain the discrepancy and which version is</span></span>
<span class="line"><span>most supported by the combined evidence.</span></span>
<span class="line"><span>Then generate one novel hypothesis that none of them</span></span>
<span class="line"><span>explicitly state but is implied by the data.</span></span></code></pre></div><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Test #8 — Devil&#39;s advocate</span></span>
<span class="line"><span>I&#39;m going to share a plan I&#39;m confident about.</span></span>
<span class="line"><span>Your job: find every way it could fail.</span></span>
<span class="line"><span>Be specific. Be ruthless.</span></span>
<span class="line"><span>Plan: [your plan]</span></span>
<span class="line"><span>Give me:</span></span>
<span class="line"><span>1. The 3 most likely failure modes</span></span>
<span class="line"><span>2. The assumption I&#39;m most wrong about</span></span>
<span class="line"><span>3. The thing I&#39;m not seeing because I want this to work</span></span></code></pre></div><h3 id="⚠️-重要隱藏事項-30-天-prompt-保留" tabindex="-1">⚠️ 重要隱藏事項：30 天 Prompt 保留 <a class="header-anchor" href="#⚠️-重要隱藏事項-30-天-prompt-保留" aria-label="Permalink to &quot;⚠️ 重要隱藏事項：30 天 Prompt 保留&quot;">​</a></h3><blockquote><p>GitHub changelog 注記：Fable 5 需保留最多 30 天的 prompt 和 output 以運行安全分類器。</p></blockquote><p>這是 Mythos-class 公開訪問的代價。上傳機密資料前需知悉。</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Fable 5 發布日（2026-06-10）的 10 個官方能力整理 + 10 個測試 prompt；最關鍵的隱藏資訊是 30 天 prompt 保留政策。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li>Fable 5 是首個公開的 Mythos-class 模型，安全測試規格最高</li><li>Vision 能力最佳（Pokémon FireRed 純視覺通關）</li><li>持久記憶對 Fable 的提升遠大於 Opus（3×）</li><li>30 天 prompt/output 保留用於安全分類器（機密資料使用前須注意）</li></ul><h3 id="關鍵數據" tabindex="-1">關鍵數據 <a class="header-anchor" href="#關鍵數據" aria-label="Permalink to &quot;關鍵數據&quot;">​</a></h3><ul><li>50M 行 Ruby 代碼庫遷移（Stripe）：原需 2 個月團隊 → 1 天</li><li>記憶提升倍數：Fable 3× vs Opus 4.8</li><li>藥物候選：14 靶點中 9 個成功，速度 10×</li><li>Jailbreak 測試：1,000+ 小時，零成功</li><li>Genomics：138 物種單細胞數據，超越 Science 論文，小 100×</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>文章是 2026-06-10 發布日整理，時效性高但工作區指導性有限</li><li>10 個測試 prompt 是實用工具，但無新框架</li><li>30 天資料保留政策是本文獨有的具體政策資訊</li><li>大多數能力 claim 引用官方文件，可信度高</li><li>同一作者在 Telegram 上銷售 hosting 服務（小幅推廣動機）</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>4/10</td><td>10 個測試 prompt 有用；30 天保留政策是政策知識；無新的工作區規則</td></tr><tr><td>B. 創新性 (20%)</td><td>6/10</td><td>30 天資料保留是本文新資訊；能力列表是已知的</td></tr><tr><td>C. 證據品質 (20%)</td><td>7.5/10</td><td>明確引用官方文件和真實合作夥伴測試（Stripe）；具體數據</td></tr><tr><td>D. 技術深度 (15%)</td><td>5.5/10</td><td>能力展示的廣度好，但缺乏工程深度</td></tr><tr><td>E. 泛化性 (15%)</td><td>6.5/10</td><td>能力展示有時效性；10 個 prompt 的框架通用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>5.7/10</strong></td><td>4×0.3+6×0.2+7.5×0.2+5.5×0.15+6.5×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Others <strong>理由</strong>：能力展示文章，工作區可行動性有限；30 天 prompt 保留政策是政策知識而非操作規則；10 個 prompt 有參考價值但不足以單獨整合進工作區規則。</p>`,29)])])}const b=e(i,[["render",l]]);export{u as __pageData,b as default};
